function iconName(n){if(n.icon)return n.icon;if(n.driveRoot)return 'drive-data';if(n.programRoot)return nodes.some(x=>x.parent===n.id)?'folder-full':'folder';if(n.kind==='folder'){const names={downloads:'downloads',desktop:'desktop',documents:'documents',dokumente:'documents',music:'music',musik:'music',pictures:'pictures',bilder:'pictures',videos:'videos'};return names[n.name.toLowerCase()]||(nodes.some(x=>x.parent===n.id)?'folder-full':'folder');}const ext=n.name.split('.').pop().toLowerCase();if(['txt','md','log','json','csv'].includes(ext))return 'text';if(['jpg','jpeg','png','gif','webp','svg','bmp'].includes(ext))return 'image';if(['mp3','wav','ogg','flac'].includes(ext))return 'audio';if(['mp4','webm','avi','mkv'].includes(ext))return 'video';if(['zip','7z','rar','tar','gz'].includes(ext))return 'archive';if(ext==='jar')return 'java';if(['exe','msi','com'].includes(ext))return 'exe';if(n.kind==='link')return 'link';if(ext==='iso')return 'iso';if(ext==='pdf')return 'pdf';return 'file';}
