document.addEventListener('click',e=>{if(!$('context').contains(e.target))$('context').hidden=true;});
function nameDialog(n=null){editing=n;$('nametitle').textContent=n?'Umbenennen':'Neuer Ordner';$('newname').value=n?.name||'';$('nameerror').textContent='';$('namedialog').showModal();$('newname').focus();}
$('nameform').onsubmit=async e=>{e.preventDefault();try{await api(editing?'/api/rename':'/api/folder',editing?{id:editing.id,name:$('newname').value}:{parent:realParent(),space:realSpace(),name:$('newname').value});$('namedialog').close();await load();}catch(e){$('nameerror').textContent=e.message;}};
function share(n){sharing=n;$('sharetext').textContent=n.kind==='folder'?'„'+n.name+'“ freigeben. Alle enthaltenen und später hinzugefügten Dateien und Unterordner werden ebenfalls öffentlich.':'„'+n.name+'“ öffentlich '+(n.kind==='link'?'als Website-Verknüpfung anzeigen.':'zum Herunterladen bereitstellen.');$('shared').checked=n.effectiveShared;$('inherited').textContent=n.effectiveShared&&!n.shared?'Dieser Eintrag erbt eine Ordnerfreigabe. Entferne das Häkchen, um ihn mit seinen Inhalten von der öffentlichen Freigabe auszunehmen.':'';$('sharelink').value=location.origin+(n.publicPath||canonical(n.id).replace('/'+encodeURIComponent(state.username)+'/','/share/'));$('sharedialog').showModal();}
$('sharesave').onclick=async()=>{try{await api('/api/share',{id:sharing.id,shared:$('shared').checked});$('sharedialog').close();await load();toast('Freigabe gespeichert');}catch(e){toast(e.message);}};
$('copylink').onclick=async()=>{try{await navigator.clipboard.writeText($('sharelink').value);toast('Link kopiert');}catch{$('sharelink').select();toast('Link markieren und mit Strg+C kopieren');}};
for(const [b,d] of [['namecancel','namedialog'],['sharecancel','sharedialog']])$(b).onclick=()=>$(d).close();
$('newfolder').onclick=()=>nameDialog();$('upload').onclick=()=>$('picker').click();
async function upload(files){if(!state.authenticated)return toast('Zum Hochladen bitte anmelden.');$('upload').disabled=true;try{for(const file of files){$('status').textContent='Wird hochgeladen: '+file.name;const result=await fetch('/api/upload?'+new URLSearchParams({name:file.name,space:realSpace(),...(realParent()?{parent:realParent()}:{})}),{method:'POST',body:file});if(!result.ok)throw Error((await result.json()).error);}toast('Upload abgeschlossen');}catch(e){toast(e.message);}finally{$('upload').disabled=false;$('picker').value='';await load();}}
$('picker').onchange=e=>upload(e.target.files);document.querySelector('.content').ondragover=e=>{if(e.dataTransfer.types.includes('Files'))e.preventDefault();};document.querySelector('.content').ondrop=e=>{if(e.dataTransfer.files.length){e.preventDefault();upload(e.dataTransfer.files);}};$('search').oninput=()=>{selection.clear();selected=null;render();};$('up').onclick=()=>go(parentOf(current));$('back').onclick=()=>{if(history.length){history.pop();forwardSteps++;window.history.back();}};$('view').onclick=()=>{details=!details;render();};$('organize').onclick=()=>{const n=nodes.find(n=>n.id===selected);if(n){const r=$('organize').getBoundingClientRect();context(n,r.left,r.bottom);}else toast('Wähle zuerst eine Datei oder einen Ordner aus.');};
window.addEventListener('popstate',()=>load().catch(e=>toast(e.message)));load().then(()=>{if(!isolatedApp&&(entryPath==='/'||entryApp)){document.getElementById('explorer-window').close();if(entryApp){const node=entryApp.path&&nodes.find(n=>decodeURIComponent(n.path).replace(/\/$/,'')===decodeURIComponent(entryApp.path).replace(/\/$/,''));if(entryApp.path&&!node){toast('Datei oder Ordner nicht gefunden oder nicht freigegeben.');return;}if(entryApp.app==='trash')trash.open();else if(entryApp.app==='explorer'){if(node?.kind==='folder'){go(node.id,false);desktop.show('explorer-window');}else if(!node)desktop.show('explorer-window');else toast('Bitte einen Ordner wählen.');}else if(node){if(entryApp.app==='editor')openText(node,true);else if(entryApp.app==='photo')openPhoto(node);else if(entryApp.app==='media')openMedia(node);else open(node);}else launchApp(entryApp.app);}}if(isolatedApp){const app=isolatedApp;if(app==='explorer'){document.body.classList.add('explorer-instance');if(isolatedNode&&get(isolatedNode)?.kind==='folder')go(isolatedNode,false);else go('@home',false);parent.postMessage({type:'explorer-ready'},location.origin);}if(['photo','media'].includes(app)){document.body.classList.add('app-instance');if(isolatedNode&&get(isolatedNode)){if(app==='photo')openPhoto(get(isolatedNode));else openMedia(get(isolatedNode));}else launchApp(app);}}}).catch(e=>toast(e.message));

