const dialog=make('dialog',undefined,'text-app-window'),bar=make('header',undefined,'viewerbar'),title=make('span',n.name),min=make('button','−'),max=make('button','□'),close=make('button','×'),status=make('p',undefined,'editor-document-status'),field=make('textarea',undefined,'editor-source');
