function photoStep(direction){if(photoQueue.length<2)return;const index=photoQueue.findIndex(n=>n.id===photoNode?.id);showPhoto(photoQueue[(index+direction+photoQueue.length)%photoQueue.length]);}
function setPhotoZoom(nextScale,anchorX=0,anchorY=0){if($('viewerimage').hidden)return;const next=zoomAt({scale:photoScale,nextScale,x:photoX,y:photoY,anchorX,anchorY});photoMode='manual';photoZoom=next.scale;photoX=next.x;photoY=next.y;layoutPhoto();}
function zoomPhoto(factor){setPhotoZoom(photoScale*factor);}
function fitPhoto(){photoMode='fit';photoX=photoY=0;layoutPhoto();}
function actualPhoto(){photoMode='manual';photoZoom=1;photoX=photoY=0;layoutPhoto();}
function rotatePhoto(delta){photoAngle=(photoAngle+delta+360)%360;photoX=photoY=0;layoutPhoto();}
function stopSlideshow(){clearInterval(photoTimer);photoTimer=null;$('photoslideshow').setAttribute('aria-pressed','false');$('photoslideshow').setAttribute('aria-label','Diashow starten');$('photoslideshow').title='Diashow starten (Leertaste)';}
