$('photoprev').onclick=()=>photoStep(-1);$('photonext').onclick=()=>photoStep(1);$('photozoomin').onclick=()=>zoomPhoto(1.25);$('photozoomout').onclick=()=>zoomPhoto(.8);$('photozoomslider').oninput=e=>setPhotoZoom(Number(e.target.value)/100);
$('photofit').onclick=fitPhoto;$('photoactual').onclick=actualPhoto;$('photorotateleft').onclick=()=>rotatePhoto(-90);$('photorotateright').onclick=()=>rotatePhoto(90);$('photoslideshow').onclick=toggleSlideshow;
