async function togglePhotoFullscreen(){const viewer=$('viewer'),frame=$('photowindow');if(document.fullscreenElement===frame)await document.exitFullscreen();else if(viewer.classList.contains('photo-fullscreen'))viewer.classList.remove('photo-fullscreen');else{try{await frame.requestFullscreen();}catch{viewer.classList.add('photo-fullscreen');}}syncPhotoFullscreen();}
