$('viewer').addEventListener('keydown',e=>{if(e.target.matches('input'))return;if(e.code==='Space'&&e.target.closest('button,a'))return;if(e.key==='ArrowLeft'){e.preventDefault();photoStep(-1);}if(e.key==='ArrowRight'){e.preventDefault();photoStep(1);}if(e.key==='+'||e.key==='='){e.preventDefault();zoomPhoto(1.25);}if(e.key==='-'){e.preventDefault();zoomPhoto(.8);}if(e.code==='Space'){e.preventDefault();toggleSlideshow();}if(e.key==='0')fitPhoto();if(e.key==='1')actualPhoto();if(e.key.toLowerCase()==='f')togglePhotoFullscreen();if(e.key==='Escape'){e.preventDefault();if(document.fullscreenElement||$('viewer').classList.contains('photo-fullscreen'))togglePhotoFullscreen();else closePhoto();}});
