function launchInstance(app,node){const dialog=make('dialog',undefined,'independent-app-window'),bar=make('header'),title=make('span',app==='explorer'?'Explorer':app==='photo'?'Fotoanzeige':'VLC media player'),min=make('button'),max=make('button'),close=make('button'),frame=make('iframe');if(app==='explorer'){dialog.classList.add('explorer-instance-window');frame.style.visibility='hidden';}dialog.id='app-instance-'+(++appInstanceNumber);title.id=dialog.id+'-title';frame.title=title.textContent;frame.allowFullscreen=true;frame.src='/app-instance?app='+app+(state.readonly&&!state.shareEditing?'&public=1':'')+(node?'&node='+encodeURIComponent(node.id):'');bar.append(title,min,max,close);dialog.append(bar,frame);document.body.append(dialog);desktop.register(dialog,{bar,title,minimizeButton:min,maximizeButton:max,closeButton:close,appId:app,icon:app==='explorer'?'/icons/explorer.png':app==='photo'?'/icons/photo-app.png':'/icons/vlc.png',minWidth:580,minHeight:380});let observer;frame.onload=()=>{const inner=frame.contentDocument?.getElementById(app==='explorer'?'explorer-caption':app==='photo'?'viewertitle':'mediatitle');if(inner){const update=()=>title.textContent=inner.textContent;observer=new MutationObserver(update);observer.observe(inner,{subtree:true,childList:true,characterData:true});update();}};dialog.addEventListener('close',()=>{observer?.disconnect();if(app!=='explorer')restoreExplorerPath(node);frame.src='about:blank';desktop.unregister(dialog.id);dialog.remove();});desktop.show(dialog.id);}
