function explorerLocation(){let n=get(current),trail=[];if(current==='@computer')trail=[get('@computer')];else if(current==='@drive')trail=[get('@computer'),get('@drive')];else if(current==='@users')trail=[get('@computer'),get('@drive'),get('@users')];else{let p=n,seen=new Set();while(p&&!p.virtual&&!seen.has(p.id)){seen.add(p.id);trail.unshift(p);p=get(p.parent);}trail=trail[0]?.driveRoot?[get('@computer'),...trail]:[get('@computer'),get('@drive'),...(trail[0]?.programRoot?[]:[get('@users'),...(trail[0]?.userRoot?[]:[get('@home')])]),...trail];}return{items:trail,name:n?.name||'Computer',path:canonical(current),canForward:forwardSteps>0,details:details&&current!=='@computer',readonly:!state.authenticated};}
chrome=createExplorerChrome({getLocation:explorerLocation,getHistory:()=>history.map(get).filter(Boolean),getMenus:()=>({'Datei':[{name:'Neues Explorer-Fenster',run:()=>launchApp('explorer')},{name:'Öffnen',disabled:!selected,run:()=>open(get(selected))},{name:'Neuer Ordner',disabled:!state.authenticated||get(current)?.writable===false,run:()=>nameDialog()},{name:'Dateien hochladen',disabled:!state.authenticated,run:()=>$('picker').click()},{name:'Schließen',run:()=>{if(isolatedApp==='explorer')parent.postMessage({type:'explorer-close'},location.origin);else $('explorer-window').close();}}],'Bearbeiten':[{name:'Kopieren',disabled:!state.authenticated||!selection.size,run:copySelection},{name:'Ausschneiden',disabled:!state.authenticated||!selection.size,run:cutSelection},{name:'Einfügen',disabled:!state.authenticated||!clipboardIds().length,run:()=>pasteSelection()},{name:'Alle auswählen',run:()=>{selection.clear();for(const id of visibleIds())selection.add(id);paintSelection();}}],'Ansicht':[{name:details?'Große Symbole':'Details',run:()=>{details=!details;render();}},{name:'Aktualisieren',run:()=>load().catch(e=>toast(e.message))}],'Extras':[{name:'Übergeordneter Ordner',run:()=>go(parentOf(current))},{name:'Programme',run:()=>go('@programs')}],'Hilfe':[{name:'Hilfe und Support',run:desktopHelp}]}),children,image,navigate:id=>go(id,true,{root:'@computer',shortcut:null}),forward:()=>{if(forwardSteps){history.push(current);forwardSteps--;window.history.forward();}},refresh:()=>load().catch(e=>toast(e.message)),help:desktopHelp,resolvePath:value=>{const path=value.trim().split(String.fromCharCode(92)).join('/').replace(/^C:/i,'/C').replace(/\/$/,'');return nodes.find(n=>n.kind==='folder'&&decodeURIComponent(n.path).replace(/\/$/,'')===decodeURIComponent(path))?.id||({'/C':'@drive','/C/Users':'@users',[canonical('@home').replace(/\/$/,'')]:'@home'})[path];},notify:toast});chrome.refresh();

window.addEventListener('message',async e=>{if(e.origin!==location.origin||!['explorer-open','explorer-new','explorer-ready','explorer-close','explorer-changed'].includes(e.data?.type))return;const source=[...document.querySelectorAll('.explorer-instance-window>iframe')].find(f=>f.contentWindow===e.source);if(!source)return;if(e.data.type==='explorer-changed'){await load();return;}if(e.data.type==='explorer-ready'){source.style.visibility='visible';return;}if(e.data.type==='explorer-close'){source.closest('dialog').close();return;}if(e.data.type==='explorer-new'){launchInstance('explorer',get(e.data.id)||get(current));return;}let node=get(e.data.id);if(!node){await load();node=get(e.data.id);}if(node){if(e.data.edit===true&&state.authenticated)openText(node,true);else open(node);}});
