let driveSpace=null,driveSpaceRead=0,driveSpaceLoading=false;
function driveBytes(value){const units=['B','KB','MB','GB','TB','PB'];let unit=0;while(value>=1024&&unit<units.length-1){value/=1024;unit++;}return value.toLocaleString('de-DE',{maximumFractionDigits:unit?1:0})+' '+units[unit];}
function paintDriveSpace(){for(const item of document.querySelectorAll('#list .item')){const infoData=driveSpace?.drives?.find(d=>d.id===item.dataset.id);item.querySelector('.drive-space')?.remove();const info=make('span',undefined,'drive-space'),label=make('span',!driveSpace?'Speicherplatz wird ermittelt …':!infoData?.available?'Laufwerk nicht verfügbar':driveBytes(infoData.freeBytes)+' frei von '+driveBytes(infoData.totalBytes),'drive-capacity');if(infoData?.available){const bar=make('span',undefined,'drive-meter'),fill=make('span',undefined,'drive-meter-fill'),percent=Math.max(0,Math.min(100,infoData.usedPercent));bar.classList.toggle('nearly-full',percent>=90);bar.setAttribute('role','progressbar');bar.setAttribute('aria-label','Belegter Speicher auf '+infoData.letter+':');bar.setAttribute('aria-valuemin','0');bar.setAttribute('aria-valuemax','100');bar.setAttribute('aria-valuenow',String(Math.round(percent)));bar.setAttribute('aria-valuetext',label.textContent);fill.style.width=percent+'%';bar.append(fill);info.append(bar);}info.append(label);item.append(info);}}

async function refreshDriveSpace(){if(driveSpaceLoading||Date.now()-driveSpaceRead<30000)return;driveSpaceLoading=true;try{driveSpace=await api('/api/drives');}catch{driveSpace={available:false};}finally{driveSpaceRead=Date.now();driveSpaceLoading=false;if(current==='@computer')paintDriveSpace();}}
