function visibleIds(){return [...$('list').querySelectorAll('.item')].map(el=>el.dataset.id);}
function paintSelection(){const visible=visibleIds();for(const id of selection)if(!get(id))selection.delete(id);if(!selection.has(selected))selected=[...selection].at(-1)||null;for(const el of $('list').children){el.classList.toggle('selected',selection.has(el.dataset.id));el.classList.toggle('cut',cutIds.includes(el.dataset.id));el.setAttribute('aria-selected',String(selection.has(el.dataset.id)));}if(selection.size>1){updateStatus(null,visible.length);$('count').textContent=selection.size+' Elemente ausgewählt';}else updateStatus(get(selected),visible.length);}
function selectItem(n,e,items){if(e.shiftKey&&selectionAnchor){const ids=items.map(x=>x.id),a=ids.indexOf(selectionAnchor),b=ids.indexOf(n.id);if(!e.ctrlKey&&!e.metaKey)selection.clear();if(a>=0)for(const id of ids.slice(Math.min(a,b),Math.max(a,b)+1))selection.add(id);else selection.add(n.id);}else if(e.ctrlKey||e.metaKey){selection.has(n.id)?selection.delete(n.id):selection.add(n.id);selectionAnchor=n.id;}else{selection.clear();selection.add(n.id);selectionAnchor=n.id;}selected=n.id;paintSelection();}
function moveRoots(ids){const all=new Set(ids);return [...all].filter(id=>{let p=get(id)?.parent;const seen=new Set();while(p&&!seen.has(p)){if(all.has(p))return false;seen.add(p);p=get(p)?.parent;}return true;});}
function movableIds(){return moveRoots([...selection].filter(id=>{const n=get(id);return n&&!n.virtual&&!n.system;}));}
function cutSelection(){const ids=movableIds();if(!state.authenticated||!ids.length)return;cutIds=ids;copyIds=[];saveClipboard('cut',ids);paintSelection();toast(ids.length+' Element'+(ids.length===1?'':'e')+' ausgeschnitten · Im Zielordner einfügen');}
function dropFolder(id){if(!state.authenticated)return null;if(id==='@home')return '@home';const n=get(id);if(!n||n.kind!=='folder'||n.writable===false)return null;if(!n.virtual)return id;if(['@desktop','@downloads','@documents','@music','@pictures','@videos'].includes(id))return nodes.find(x=>x.system&&x.space===id.slice(1))?.id||null;return null;}
function canDrop(ids,targetId){const target=dropFolder(targetId);if(!ids.length||!target)return false;const normalized=moveRoots(ids);return normalized.every(id=>{const n=get(id);if(!n||n.system||n.virtual)return false;let p=target;const seen=new Set();while(p&&!seen.has(p)){if(p===id)return false;seen.add(p);p=get(p)?.parent;}return true;})&&normalized.some(id=>get(id)?.parent!==target);}
async function moveSelection(ids,targetId){const target=dropFolder(targetId);if(!canDrop(ids,targetId))return toast('Bitte einen anderen gültigen Zielordner auswählen.');try{const result=await api('/api/move',{ids:moveRoots(ids),parent:target});cutIds=cutIds.filter(id=>!ids.includes(id));selection.clear();selected=null;await load();toast(result.moved+' Element'+(result.moved===1?'':'e')+' verschoben');return true;}catch(e){toast(e.message);return false;}}
function saveClipboard(mode,ids){try{sessionStorage.setItem('windows7.clipboard',JSON.stringify({owner:state.userId,mode,ids}));}catch{}}
function readClipboard(){try{const value=JSON.parse(sessionStorage.getItem('windows7.clipboard'));if(value?.owner===state.userId&&Array.isArray(value.ids))return value;}catch{}return {mode:typeof copyIds!=='undefined'&&copyIds.length?'copy':'cut',ids:typeof copyIds!=='undefined'&&copyIds.length?copyIds:cutIds};}
function clipboardIds(){return readClipboard().ids;}
function copySelection(){const ids=movableIds();if(!state.authenticated||!ids.length)return;copyIds=ids;cutIds=[];saveClipboard('copy',ids);paintSelection();toast(ids.length+' Element(e) kopiert');}
async function pasteSelection(id=current){const clip=readClipboard(),parent=dropFolder(id);if(!state.authenticated||!parent||!clip.ids.length)return;if(clip.mode==='copy'){try{const result=await api('/api/copy',{ids:clip.ids,parent});await load();toast(result.copied+' Element(e) kopiert');}catch(error){toast(error.message);}}else if(await moveSelection(clip.ids,id)){cutIds=[];saveClipboard('cut',[]);}}

async function deleteSelection(){const ids=movableIds();if(!ids.length)return;if(ids.length===1)return deleteNode(get(ids[0]));if(!await confirmAction(ids.length+' ausgewählte Elemente in den Papierkorb verschieben?'))return;try{for(const id of ids)await api('/api/delete',{id});selection.clear();selected=null;await load();}catch(e){await load();toast(e.message);}}
function resetDragHover(){clearTimeout(dragHoverTimer);dragHoverTimer=null;dragHoverId=null;document.querySelectorAll('.drop-target').forEach(el=>el.classList.remove('drop-target'));}
function wireDragSource(el,n){el.draggable=!!state.authenticated&&!n.virtual&&!n.system;el.addEventListener('dragstart',e=>{if(!el.draggable)return;if(!selection.has(n.id)){selection.clear();selection.add(n.id);selected=n.id;paintSelection();}dragIds=movableIds();if(!dragIds.length){e.preventDefault();return;}e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('application/x-explorer-nodes',JSON.stringify(dragIds));e.dataTransfer.setData('text/plain',dragIds.map(id=>get(id).name).join(', '));});el.addEventListener('dragend',()=>{dragIds=[];resetDragHover();});}
function wireDropTarget(el,id,onHover){el.addEventListener('dragover',e=>{if(!dragIds.length||!canDrop(dragIds,id))return;e.preventDefault();e.stopPropagation();e.dataTransfer.dropEffect='move';el.classList.add('drop-target');if(dragHoverId!==id){resetDragHover();el.classList.add('drop-target');dragHoverId=id;if(onHover)dragHoverTimer=setTimeout(()=>{dragHoverTimer=null;onHover();},900);}});el.addEventListener('dragleave',e=>{if(!el.contains(e.relatedTarget)&&dragHoverId===id)resetDragHover();});el.addEventListener('drop',e=>{if(!dragIds.length)return;e.preventDefault();e.stopPropagation();const ids=[...dragIds];dragIds=[];resetDragHover();moveSelection(ids,id);});}
// Resolve the current folder lazily as navigation can change while dragging.
const contentArea=document.querySelector('.content');
contentArea.addEventListener('dragover',e=>{if(e.target.closest('.item')||!canDrop(dragIds,current))return;e.preventDefault();e.dataTransfer.dropEffect='move';});
contentArea.addEventListener('drop',e=>{if(e.defaultPrevented||!dragIds.length)return;e.preventDefault();const ids=[...dragIds];dragIds=[];resetDragHover();moveSelection(ids,current);});
contentArea.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('.item,button,input,a')||document.querySelector('dialog[open]:not(.desktop-window)'))return;const bounds=contentArea.getBoundingClientRect(),base=e.ctrlKey||e.metaKey||e.shiftKey?new Set(selection):new Set();if(!base.size){selection.clear();selected=null;paintSelection();}const box=make('div',undefined,'selection-box');contentArea.append(box);marquee={pointer:e.pointerId,x:e.clientX-bounds.left+contentArea.scrollLeft,y:e.clientY-bounds.top+contentArea.scrollTop,base,box};contentArea.setPointerCapture(e.pointerId);document.body.classList.add('selecting-files');e.preventDefault();});
contentArea.addEventListener('pointermove',e=>{if(!marquee||e.pointerId!==marquee.pointer)return;const bounds=contentArea.getBoundingClientRect();if(e.clientY>bounds.bottom-24)contentArea.scrollTop+=16;else if(e.clientY<bounds.top+24)contentArea.scrollTop-=16;const x=e.clientX-bounds.left+contentArea.scrollLeft,y=e.clientY-bounds.top+contentArea.scrollTop,left=Math.min(x,marquee.x),top=Math.min(y,marquee.y),right=Math.max(x,marquee.x),bottom=Math.max(y,marquee.y);Object.assign(marquee.box.style,{left:left+'px',top:top+'px',width:right-left+'px',height:bottom-top+'px'});selection.clear();for(const id of marquee.base)selection.add(id);if(right-left>3||bottom-top>3)for(const item of $('list').children){const r=item.getBoundingClientRect(),ix=r.left-bounds.left+contentArea.scrollLeft,iy=r.top-bounds.top+contentArea.scrollTop;if(ix<right&&ix+r.width>left&&iy<bottom&&iy+r.height>top)selection.add(item.dataset.id);}paintSelection();});
function endMarquee(){if(!marquee)return;marquee.box.remove();marquee=null;document.body.classList.remove('selecting-files');}
for(const name of ['pointerup','pointercancel','lostpointercapture'])contentArea.addEventListener(name,endMarquee);
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]:not(.desktop-window)')||e.target.closest('input,textarea,select,[contenteditable],.desktop-window:not(.explorer-window)'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='a'){e.preventDefault();selection.clear();for(const id of visibleIds())selection.add(id);paintSelection();}if(state.authenticated&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='c'){e.preventDefault();copySelection();}if(state.authenticated&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='x'){e.preventDefault();cutSelection();}if(state.authenticated&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='v'){e.preventDefault();pasteSelection();}if(e.key==='Escape'){cutIds=[];endMarquee();resetDragHover();paintSelection();}});
